
.quest-panel {
  padding: 8px 10px;
}

.section-title {
  font-size: 0.8rem;
  font-weight: bold;
  color: var(--c-sepia-dark);
  margin-bottom: 6px;
  letter-spacing: 1px;
  font-family: var(--font-mono);
}

.main-quest {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 5px 7px;
  background: linear-gradient(90deg, rgba(139, 26, 26, 0.06) 0%, transparent 100%);
  border-left: 3px solid var(--c-crimson);
}

.quest-tag {
  font-size: 0.6rem;
  font-weight: bold;
  padding: 1px 5px;
  border-radius: 2px;
  font-family: var(--font-mono);
  white-space: nowrap;

  &.main-tag {
    background: var(--c-crimson);
    color: var(--c-parchment);
  }
}

.quest-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.quest-name {
  font-size: 0.75rem;
  font-weight: bold;
  color: var(--c-ink);
}

.quest-time {
  font-size: 0.65rem;
  color: var(--c-crimson-dim);
  font-family: var(--font-mono);
}
