
.roster {
  padding: 8px 10px;
  border-bottom: 1px solid var(--c-sepia-light);
}

.section-title {
  font-size: 0.8rem;
  font-weight: bold;
  color: var(--c-sepia-dark);
  margin-bottom: 6px;
  letter-spacing: 1px;
  font-family: var(--font-mono);
}

.char-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(155px, 1fr));
  gap: 4px;
}

.char-card {
  border: 1px solid var(--c-sepia-light);
  padding: 5px 7px;
  cursor: pointer;
  transition: all 0.2s;
  background: rgba(255,255,255,0.4);

  &:hover {
    border-color: var(--c-gold);
    background: rgba(255,255,255,0.8);
  }

  &.char-active {
    border-left: 3px solid var(--c-crimson);
    background: linear-gradient(90deg, rgba(139, 26, 26, 0.05) 0%, rgba(255,255,255,0.4) 100%);
  }
}

.char-header {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-bottom: 3px;
}

.char-name {
  font-size: 0.78rem;
  font-weight: bold;
  color: var(--c-ink);
}

.char-code {
  font-size: 0.6rem;
  color: var(--c-crimson-dim);
}

.char-affection {
  display: flex;
  align-items: center;
  gap: 4px;
}

.aff-bar-wrap {
  flex: 1;
  height: 4px;
  background: rgba(0,0,0,0.06);
  border-radius: 2px;
  overflow: hidden;
}

.aff-bar {
  height: 100%;
  border-radius: 2px;
  transition: width 0.8s ease;
}

.aff-val {
  font-size: 0.6rem;
  font-family: var(--font-mono);
  color: var(--c-sepia-mid);
  width: 32px;
  text-align: right;
}

.char-locked {
  font-size: 0.65rem;
  color: var(--c-sepia-light);
  font-style: italic;
}

.lock-icon {
  font-size: 0.7rem;
}

.char-detail {
  margin-top: 5px;
  padding-top: 5px;
  border-top: 1px dashed var(--c-sepia-light);
}

.detail-row {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 4px;
  font-size: 0.68rem;
}

.detail-label {
  color: var(--c-sepia-mid);
  font-size: 0.6rem;
}

.stage-badge {
  padding: 0 4px;
  border-radius: 2px;
  font-weight: bold;
  font-size: 0.65rem;

  &.stage-0 { background: var(--c-slate-light); color: var(--c-parchment); }
  &.stage-1 { background: var(--c-gold); color: var(--c-ink); }
  &.stage-2 { background: var(--c-crimson-dim); color: var(--c-parchment); }
  &.stage-3 { background: var(--c-crimson); color: var(--c-parchment); }
}

.body-status {
  display: flex;
  gap: 6px;
}

.body-part {
  display: flex;
  align-items: center;
  gap: 1px;
}

.body-icon {
  font-size: 0.7rem;
}

.body-state {
  font-size: 0.65rem;
  &.body-纯洁 { color: var(--c-slate-light); }
  &.body-经验 { color: var(--c-crimson); }
}
