
.player-panel {
  padding: 8px 10px;
  border-bottom: 1px solid var(--c-sepia-light);
  background: linear-gradient(90deg, rgba(201, 168, 76, 0.08) 0%, transparent 100%);
}

.section-title {
  font-size: 0.8rem;
  font-weight: bold;
  color: var(--c-sepia-dark);
  margin-bottom: 6px;
  letter-spacing: 1px;
  font-family: var(--font-mono);
}

.skills-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 12px;
  margin-bottom: 6px;
}

@media (max-width: 480px) {
  .skills-row {
    grid-template-columns: 1fr;
  }
}

.skill {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.72rem;
}

.skill-icon {
  font-size: 0.85rem;
}

.skill-name {
  width: 28px;
  color: var(--c-sepia-mid);
}

.skill-bar-wrap {
  flex: 1;
  height: 5px;
  background: rgba(0,0,0,0.08);
  border-radius: 2px;
  overflow: hidden;
}

.skill-bar {
  height: 100%;
  border-radius: 2px;
  transition: width 0.6s ease;
}

.skill-val {
  width: 42px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--c-sepia-mid);
}

.resource-row {
  display: flex;
  gap: 12px;
  font-size: 0.72rem;
  color: var(--c-sepia-mid);
  flex-wrap: wrap;
}

.res-item strong {
  color: var(--c-ink);
}

.res-unit {
  color: var(--c-sepia-light);
  font-size: 0.65rem;
}
